<section class="admin-welcome"><div><p class="eyebrow">SUIVI PÉDAGOGIQUE</p><h1>Inscriptions aux cours</h1><p>Suivez chaque apprenant, son activation et sa progression.</p></div><a class="btn secondary" href="/admin/utilisateurs">Gérer les comptes</a></section><section class="panel"><div class="table-toolbar"><label class="search"><i data-icon="search"></i><input data-table-search placeholder="Apprenant, téléphone ou formation..."></label><span><?= count($items) ?> inscription(s)</span></div><div class="table-responsive"><table><thead><tr><th>APPRENANT</th><th>FORMATION</th><th>INSCRIPTION</th><th>STATUT</th><th>PROGRESSION</th></tr></thead><tbody><?php foreach($items as $item): ?><tr data-search-row><td><strong><?= htmlspecialchars($item['name']) ?></strong><br><small><?= htmlspecialchars($item['email']) ?> · <?= htmlspecialchars($item['phone']??'—') ?></small></td><td><?= htmlspecialchars($item['course_title']) ?></td><td><?= date('d/m/Y H:i',strtotime($item['enrolled_at'])) ?></td><td><span class="status <?= $item['status']==='active'||$item['status']==='completed'?'published':'draft' ?>"><?= htmlspecialchars($item['status']) ?></span></td><td><div class="progress-row"><div class="progress"><span style="width:<?= (int)$item['progress'] ?>%"></span></div><b><?= (int)$item['progress'] ?>%</b></div></td></tr><?php endforeach ?></tbody></table></div><?php if(!$items): ?><div class="admin-empty">Aucune inscription enregistrée.</div><?php endif ?></section>
